function perRange(){var p=F.rep.per,t=today(),y=+t.slice(0,4),m=+t.slice(5,7),pad=function(x){return (x<10?'0':'')+x};
 if(p==='day')return [t,t];if(p==='week'){return [day(new Date(Date.parse(t)-6*864e5)),t]}
 if(p==='month')return [t.slice(0,8)+'01',t];if(p==='pmonth'){var pm=m===1?12:m-1,py=m===1?y-1:y,last=new Date(Date.UTC(py,pm,0)).getUTCDate();return [py+'-'+pad(pm)+'-01',py+'-'+pad(pm)+'-'+pad(last)]}
 if(p==='term'){try{var c=V5.curTerm61();if(c)return [c.start,c.end]}catch(e){}}
 if(p==='year')return [y+'-01-01',t];return [F.rep.from||t,F.rep.to||t]}
