 h+='<p class="mu">'+L('الفترة: ','Period: ')+'<span dir="ltr">'+e0(d.rg[0])+' → '+e0(d.rg[1])+'</span> · '+L('المصدر: تأكيدات الدفع وحدها','Source: payment confirmations only')+'</p>';
