H.fin263m=function(act,id){var r=rowOf(id);if(!r)return;var c=r.claim||{},h='<form class="v51g fin263frm" onsubmit="V51.h.fin263do(this,\''+act+'\',\''+e0(id)+'\');return false">'+sumLine(r),T='';
 if(act==='confirm'){T=L('تأكيد استلام الدفع','Confirm payment received');h+='<label>'+L('المبلغ المستلَم','Amount received')+'<input name="amount" type="number" min="0" step="0.01" required dir="ltr" value="'+e0(r.due)+'"'+(r.kind==='plt'?' readonly':'')+'></label><label>'+L('طريقة الدفع','Payment method')+'<select name="method">'+MET.map(function(m){return '<option value="'+m[0]+'">'+L(m[1],m[2])+'</option>'}).join('')+'</select></label><label>'+L('رقم العملية / المرجع','Transaction ref.')+'<input name="ref" dir="ltr" maxlength="60" value="'+e0(c.trx||'')+'"></label><label>'+L('تاريخ الدفع','Payment date')+'<input name="paidAt" type="date" required value="'+e0(c.at?day(c.at):today())+'"></label><label style="grid-column:1/-1">'+L('ملاحظة (اختياري)','Note (optional)')+'<input name="note" maxlength="300"></label><label class="v51ck" style="grid-column:1/-1"><input type="checkbox" name="rc" checked> '+L('إصدار إيصال دفع رسمي برمز QR وإرساله بالبريد','Issue an official QR payment receipt and email it')+'</label>'+(c.trx?'<p class="msg" style="grid-column:1/-1">'+L('تحقّق قبل التأكيد من وصول المبلغ برقم العملية ','Before confirming, check that the amount arrived with TrxID ')+'<b dir="ltr">'+e0(c.trx)+'</b>'+L(' من الرقم ',' from ')+'<b dir="ltr">'+e0(c.from||'')+'</b>.</p>':'')}
 else if(act==='reject'){T=L('رفض بيانات الدفع','Reject payment details');h+='<label style="grid-column:1/-1">'+L('سبب الرفض (يصل للطالب)','Reason (sent to the student)')+'<textarea name="note" required minlength="5" rows="3"></textarea></label>'}
 else if(act==='sch'){T=L('تطبيق منحة','Apply a scholarship');var o='';for(var i=0;i<=100;i+=5)o+='<option value="'+i+'"'+(+r.pct===i?' selected':'')+'>'+i+'%</option>';h+='<label>'+L('نسبة المنحة','Scholarship percentage')+'<select name="pct">'+o+'</select></label>'+(r.kind==='sem'&&stuOf(r.ref)?'<label class="v51ck" style="grid-column:1/-1"><input type="checkbox" name="rec" checked> '+L('تسجيلها منحةً رسمية للطالب لهذا الفصل (تظهر في ملفه وسجل المنح)','Record it as an official scholarship for this student and semester (shown in their file and the scholarship register)')+'</label>':'')+'<label style="grid-column:1/-1">'+L('سبب المنحة أو أساسها','Reason or basis')+'<input name="note" required maxlength="300"></label>'}
 else if(act==='remind'){T=L('إرسال تذكير بالدفع','Send a payment reminder');h+='<p style="grid-column:1/-1">'+L('يُرسل للطالب بريد رسمي يذكّره بالمبلغ وموعد الدفع وطريقته.','The student receives an official email with the amount, deadline and how to pay.')+(r.rem_n?' '+L('أُرسل له من قبل '+r.rem_n+' تذكير.',r.rem_n+' reminders already sent.'):'')+'</p>'}
 else if(act==='due_at'){T=L('تعديل موعد الدفع','Change the payment deadline');h+='<label>'+L('آخر موعد للدفع','Payment deadline')+'<input name="due_at" type="date" required value="'+e0(r.due_at||'')+'"></label><label style="grid-column:1/-1">'+L('السبب (اختياري)','Reason (optional)')+'<input name="note" maxlength="300"></label>'}
 else if(act==='note'){T=L('ملاحظة متابعة','Follow-up note');h+='<label style="grid-column:1/-1">'+L('الملاحظة (للإدارة فقط)','Note (administration only)')+'<textarea name="note" required rows="3" maxlength="500"></textarea></label>'}
 else if(act==='cancel'){T=L('إلغاء المطالبة','Cancel the claim');h+='<label style="grid-column:1/-1">'+L('السبب','Reason')+'<input name="note" required maxlength="300"></label>'}
 else if(act==='restore'){T=L('استعادة المطالبة','Restore the claim');h+='<label style="grid-column:1/-1">'+L('السبب (اختياري)','Reason (optional)')+'<input name="note" maxlength="300"></label>'}
 else if(act==='void'){T=L('إبطال تأكيد الدفع','Void the payment confirmation');h+='<p class="msg er" style="grid-column:1/-1">'+L('يعود المبلغ مستحقاً ويُستبعد من الحسابات. ألغِ الإيصال أيضاً من «المدفوعات والإيصالات» إن صدر.','The amount becomes due again and is removed from the accounts. Also void the receipt in “Payments & Receipts” if one was issued.')+'</p><label style="grid-column:1/-1">'+L('سبب الإبطال (يُسجَّل)','Reason (recorded)')+'<input name="note" required minlength="5" maxlength="300"></label>'}
 h+='<div style="grid-column:1/-1"><button class="btn">'+L('تنفيذ','Confirm')+'</button> <button type="button" class="btn s" onclick="closeMdl()">'+L('رجوع','Back')+'</button></div></form>';
 try{mdl(T,h)}catch(e){}};
H.fin263do=async function(f,act,id){var r=rowOf(id);if(!r)return;var b=f.querySelector('button.btn');if(b)b.disabled=true;var v={};[].slice.call(f.elements).forEach(function(x){if(x.name)v[x.name]=x.type==='checkbox'?x.checked:x.value});
 var p={note:v.note||''};if(act==='confirm'){p.amount=v.amount;p.method=v.method;p.ref=v.ref;p.paidAt=v.paidAt}else if(act==='sch')p.pct=v.pct;else if(act==='due_at')p.due_at=v.due_at;
 if(act==='sch'&&v.rec&&r.kind==='sem'){try{var s=stuOf(r.ref);if(s&&V5.grant72){V5.grant72(s,'term',r.term,+v.pct,v.note||'');save()}}catch(e){}}
 var res=null;try{res=await sb.rpc('fin_admin',{act:act,p_id:id,p:p})}catch(e){res={error:e}}var d=res&&res.data;
 if(!(d&&d.ok)){toast(L('تعذّر التنفيذ: ','Could not complete: ')+String((d&&d.error)||(res&&res.error&&res.error.message)||''));if(b)b.disabled=false;return}
 try{closeMdl()}catch(e){}toast(L('تم.','Done.'));
 if(act==='confirm'&&v.rc){await reread();var r2=rowOf(id);if(r2&&r2.status==='confirmed')await receipt(r2,{method:v.method,ref:v.ref,paidAt:v.paidAt})}
 F.rows=null;load(1)};
/* v274: بيانات المتقدم لاختبار تحديد المستوى عبر plt_list (الجدول مغلق للقراءة المباشرة) */async function pltOf(id){try{var q=await sb.rpc('plt_list',{});var R=(q&&q.data)||[];var x=R.find(function(y){return String(y.id)===String(id)});return (x&&x.data)||{}}catch(e){return {}}}
async function receipt(r,o){o=o||{};var k=r.conf||{},nm=r.name,nmEn='',em='',sid='',pay;
 try{if(r.kind==='plt'){var dd=await pltOf(r.ref);nm=dd.nameAr||nm;nmEn=W.nameEn274?nameEn274(dd.nameEn,nm):(dd.nameEn||'');em=dd.email||'';pay={kind:'fee',ptype:'person',descAr:'رسوم اختبار تحديد المستوى',descEn:'Placement test fee',base:+r.base,pct:+r.pct,due:+r.due,amount:+k.amount||+r.due,cur:r.cur,method:o.method||k.method||'bkash',ref:o.ref||k.ref||(r.claim||{}).trx||'',paidAt:o.paidAt||day(k.at),reqId:r.id,email:em}}
  else{var s=stuOf(r.ref)||{},P=progOf(s.prog)||{},tn={ar:'',en:''};try{var t=V5.termById61(r.term);if(t)tn=V5.termNames61(t)}catch(e){}nm=s.name||nm;nmEn=W.nameEn274?nameEn274(s.nameEn,nm):(s.nameEn||'');em=s.email||'';sid=s.id||r.ref;pay={kind:'fee',ptype:'student',prog:s.prog,progAr:P.name||'',progEn:(P.eng&&P.eng.nameEn)||'',term:r.term,termAr:tn.ar,termEn:tn.en,descAr:r.kind==='sem'?'الرسوم الدراسية للفصل الدراسي':(r.descr||''),descEn:r.kind==='sem'?'Semester tuition fees':(r.descr||''),base:+r.base,pct:+r.pct,due:+r.due,amount:+k.amount||+r.due,cur:r.cur,method:o.method||k.method||'bkash',ref:o.ref||k.ref||(r.claim||{}).trx||'',paidAt:o.paidAt||day(k.at),reqId:r.id,email:em}}
  var c=V5.issueReceipt71({name:nm,nameEn:nmEn,sid:sid,date:today(),pay:pay});save();
  await sb.rpc('fin_admin',{act:'rcpt',p_id:r.id,p:{rcpt:c.rec}});
  toast(L('صدر الإيصال رقم ','Receipt issued No. ')+c.rec);
  if(o.to)em=o.to;if(o.noSend)em='';if(em&&/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(em)&&V5.sendReceipt71){var x=await V5.sendReceipt71(c.rec,em);if(o.out)o.out.sent=!!(x&&x.ok);toast(x&&x.ok?L('أُرسل الإيصال إلى ','Receipt sent to ')+em:L('لم يُرسل الإيصال بالبريد؛ أرسله من «المدفوعات والإيصالات».','The receipt was not emailed; send it from “Payments & Receipts”.'))}
  return c}catch(e){toast(L('تعذّر إصدار الإيصال: ','Could not issue the receipt: ')+String((e&&e.message)||e))}}
/* v272: إيصالات المدفوعات المؤكَّدة — معاينة إلى بريد المعهد أولاً، ثم الإرسال إلى الدافعين بعد موافقة الإدارة */
W.fin263rcptBatch=async function(mode){var out={mode:mode,n:0,sent:0,err:[]};try{await load(1);var hm=await sb.from('settings').select('data').eq('key','home').maybeSingle();var inst=String((hm&&hm.data&&hm.data.data&&hm.data.data.em)||'').trim();
 var R=(F.rows||[]).filter(function(r){return r.kind==='plt'&&r.status==='confirmed'});
 var fixEn=async function(r){try{var c0=(S.certs||[]).find(function(x){return x.rec===r.rcpt});var dd=await pltOf(r.ref);if(c0&&dd.nameEn&&c0.nameEn!==dd.nameEn){c0.nameEn=dd.nameEn;c0.nameEnAuto=0;save()}}catch(e){}};
 if(mode==='preview'){for(var i=0;i<R.length;i++){var r=R[i];out.n++;if(r.rcpt){await fixEn(r);var x=await V5.sendReceipt71(r.rcpt,inst);if(x&&x.ok)out.sent++;else out.err.push(String(x&&x.error||'x'));continue}
   var o={to:inst,out:{}};var c=await receipt(r,o);if(o.out.sent)out.sent++;else out.err.push(c?'mail':'issue');try{await sb.rpc('fin_admin',{act:'note',p_id:r.id,p:{note:'معاينة الإيصال '+(c&&c.rec||'')+' أُرسلت إلى بريد المعهد بانتظار موافقة الإدارة'}})}catch(e){}}}
 else if(mode==='send'){for(var j=0;j<R.length;j++){var r2=R[j];if(!r2.rcpt)continue;if(JSON.stringify(r2.notes||'').indexOf('rcpt-sent')>=0)continue;out.n++;await fixEn(r2);var em=String((await pltOf(r2.ref)).email||'').trim();
   var y=await V5.sendReceipt71(r2.rcpt,em);if(y&&y.ok){out.sent++;try{await sb.rpc('fin_admin',{act:'note',p_id:r2.id,p:{note:'rcpt-sent: أُرسل الإيصال '+r2.rcpt+' إلى الدافع بعد موافقة الإدارة'}})}catch(e){}}else out.err.push(String(y&&y.error||'x'))}}
 }catch(e){out.err.push(String(e&&e.message||e).slice(0,80))}return out};
H.fin263rc=async function(id){var r=rowOf(id);if(!r||r.status!=='confirmed'||r.rcpt)return;if(!confirm(L('إصدار إيصال دفع رسمي لهذه الدفعة وإرساله بالبريد؟','Issue an official payment receipt for this payment and email it?')))return;await receipt(r);F.rows=null;load(1)};
H.fin263remAll=async function(){var R=(F.rows||[]).filter(function(r){return r.kind==='sem'&&late(r)>0});if(!R.length)return;if(!confirm(L('إرسال تذكير بالبريد إلى '+R.length+' طالباً متأخراً؟','Email a reminder to '+R.length+' overdue students?')))return;var n=0;for(var i=0;i<R.length;i++){try{var x=await sb.rpc('fin_admin',{act:'remind',p_id:R[i].id,p:{}});if(x&&x.data&&x.data.ok)n++}catch(e){}}toast(L('أُرسل تذكير إلى ','Reminders sent: ')+n);F.rows=null;load(1)};
H.fin263gen=async function(){var t=(document.getElementById('fin263term')||{}).value;if(!t)return;var it=(S.students||[]).filter(function(s){return regd(s)&&!s.test240}).map(function(s){return itemFor(s,t)}).filter(Boolean);if(!it.length){toast(L('لا يوجد طلاب منتظمون.','No registered students.'));return}
 if(!confirm(L('إصدار رسوم ','Issue the fees of ')+tName(t)+L(' لعدد ',' for ')+it.length+L(' طالباً منتظماً؟ يُرسل لكل طالب بريد رسمي بالمستحق (لمن لم تصدر له من قبل).',' registered students? Each student without an existing claim receives an official email.')))return;
 var res=null;try{res=await sb.rpc('fin_admin',{act:'sem',p_id:null,p:{items:it}})}catch(e){res={error:e}}var d=res&&res.data;if(d&&d.ok){toast(L('صدرت: ','Issued: ')+d.created+L(' · حُدّثت: ',' · updated: ')+d.updated);F.rows=null;load(1)}else toast(L('تعذّر الإصدار.','Could not issue.'))};
H.fin263add=async function(f){var p={ref:f.ref.value.trim(),name:f.name.value.trim(),descr:f.descr.value.trim(),amount:+f.amount.value,cur:f.cur.value,due_at:f.due_at.value};var res=null;try{res=await sb.rpc('fin_admin',{act:'add',p_id:null,p:p})}catch(e){}if(res&&res.data&&res.data.ok){toast(L('أُضيف.','Added.'));F.rows=null;load(1)}else toast(L('تعذّرت الإضافة.','Could not add.'))};
async function saveCfg(patch){var c=Object.assign({},cfgOf());delete c.bkash;Object.assign(c,patch);var r=await sb.from('v51_settings').upsert({key:'fin263',data:c});if(r&&r.error){toast(L('تعذّر الحفظ.','Could not save.'));return}F.cfg=Object.assign({},F.cfg,patch);toast(L('حُفظ.','Saved.'));rerender()}
H.fin263cfg=function(f){saveCfg({auto:f.auto.checked?1:0,gate:f.gate.checked?1:0,remOn:f.remOn.checked?1:0,days:Math.max(1,Math.min(120,+f.days.value||14)),remDays:Math.max(1,Math.min(60,+f.remDays.value||7)),remMax:Math.max(0,Math.min(20,+f.remMax.value||0))})};
